// InstantImages.org — instant AI image generation.
// Type a prompt → get an image in ~3 seconds. Powered by Gemini Flash Lite.

const GEMINI_MODEL = 'gemini-3.1-flash-lite-image';
const GEMINI_URL = `https://generativelanguage.googleapis.com/v1beta/models/${GEMINI_MODEL}:generateContent`;
const CEREBRAS_URL = 'https://api.cerebras.ai/v1/chat/completions';

const FALLBACK_PROMPTS = [
  'a derelict lighthouse battered by a storm at golden hour, oil painting',
  'a single red umbrella on rain-soaked cobblestones at night',
  'an astronaut sitting alone in a diner on Mars, warm light through the window',
  'a cherry blossom branch over still water at dawn, mist, minimal ink wash',
  'a vintage typewriter on a desk by a window, rain streaming down the glass',
  'a hot air balloon drifting over a foggy mountain valley at sunrise',
];

const SURPRISE_PROMPT = (
  'Give ONE visually striking image prompt — a specific concrete scene that ' +
  'would make a beautiful image. Grounded and vivid, not abstract. One sentence. ' +
  'Include a subject, setting, and mood/lighting. Examples: ' +
  "'a derelict lighthouse battered by a storm at golden hour, oil painting', " +
  "'a single red umbrella abandoned on rain-soaked cobblestones at night', " +
  "'an astronaut sitting alone in a diner on Mars, warm light through the window', " +
  "'a cherry blossom branch over still water at dawn, mist, minimal ink wash'. " +
  'Reply with ONLY the prompt, one sentence.'
);

// Whitespace here is semantically load-bearing (it's what distinguishes
// "continue this word" from "start a new word") and asking the model to just
// get a literal space character right turned out to be unreliable — so
// instead it classifies SAME/NEW explicitly (a plain categorization, which
// models are much better at than exact-character formatting) and our own
// code applies the space deterministically from that tag.
function typeaheadPrompt(prefix) {
  return (
    'You are autocompleting a text field for an AI image generator, mid-keystroke. ' +
    'Continue the user\'s EXACT partial text into a vivid, concrete, one-sentence image ' +
    'prompt (subject, setting, mood/lighting).\n\n' +
    'Output format (exact): start your reply with EXACTLY one tag, SAME or NEW, then a ' +
    'pipe character, then the continuation — nothing else.\n' +
    '- SAME: the partial text cuts off mid-word; your continuation finishes that word ' +
    '(e.g. partial \'a city street at nig\' -> \'SAME|ht, neon signs glow above rain-slick pavement\').\n' +
    '- NEW: the partial text ends on a complete word; your continuation starts a new one ' +
    '(e.g. partial \'a lighthouse\' -> \'NEW|perched on rugged cliffs, its beacon glowing at dusk\'). ' +
    'This is the more common case — when unsure, use NEW.\n\n' +
    'Never repeat any part of what they already typed (not even the word you\'re finishing ' +
    'for SAME — only the missing remainder). No quotes. Keep it under 15 words. ' +
    `Partial text: "${prefix}"`
  );
}

// Defensive cleanup: gpt-oss occasionally echoes back a bit of the prefix
// (or, for SAME, the whole word instead of just the missing remainder)
// despite instructions not to. Strip any overlap between the end of the
// user's prefix and the start of the model's completion (case-insensitive)
// so `prefix + completion` never visibly duplicates text.
function stripOverlap(prefix, completion) {
  let c = completion.trim().replace(/^["*\`]+|["*\`]+$/g, '').trim();
  const p = prefix.toLowerCase();
  const cLower = c.toLowerCase();
  const maxCheck = Math.min(p.length, cLower.length, 40);
  for (let n = maxCheck; n > 0; n--) {
    if (p.slice(p.length - n) === cLower.slice(0, n)) {
      c = c.slice(n);
      break;
    }
  }
  return c;
}

// Parses the "SAME|..." / "NEW|..." tag format and returns a completion with
// exactly the right leading space applied (or none), overlap-stripped.
function parseTypeahead(prefix, raw) {
  const pipeIdx = raw.indexOf('|');
  const tag = (pipeIdx >= 0 ? raw.slice(0, pipeIdx) : '').trim().toUpperCase();
  const body = pipeIdx >= 0 ? raw.slice(pipeIdx + 1) : raw;
  const isSame = tag === 'SAME';
  let c = stripOverlap(prefix, body);
  if (!c) return '';
  c = c.replace(/^\s+/, '');
  if (!isSame) c = ' ' + c;
  return c;
}

const EXAMPLES = [
  { prompt: 'a derelict lighthouse battered by a storm at golden hour, dramatic oil painting', data: '' },
  { prompt: 'a single red umbrella abandoned on rain-soaked cobblestones at night, cinematic', data: '' },
  { prompt: 'an astronaut sitting alone in a diner on Mars, warm light through the window, retro sci-fi', data: '' },
  { prompt: 'a cherry blossom branch over still water at dawn, mist, minimal Japanese ink wash style', data: '' },
  { prompt: 'a vintage typewriter on a desk by a window, rain streaming down the glass, moody', data: '' },
  { prompt: 'a hot air balloon drifting over a foggy mountain valley at sunrise, epic landscape', data: '' },
];

const HTML_PAGE = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>InstantImages — show me anything</title>
<meta name="description" content="Show me anything. A real image, looked at in about 3 seconds. Free, no login.">
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { background: #0b0e13; color: #e8eef4; font-family: -apple-system, system-ui, sans-serif;
         display: flex; flex-direction: column; align-items: center; min-height: 100vh; padding: 3rem 1.25rem 2rem; }
  .wordmark { color: #4c566a; font-size: 0.78rem; font-weight: 600; letter-spacing: 0.08em;
    text-transform: uppercase; margin-bottom: 2.5rem; }

  .ask { width: 100%; max-width: 480px; display: flex; align-items: baseline; gap: 0.45rem;
    margin-bottom: 1.75rem; }
  .ask-prefix { font-size: 1.5rem; font-weight: 600; color: #e8eef4; white-space: nowrap; }
  .ask-input { flex: 1; min-width: 0; background: transparent; border: none;
    border-bottom: 2px solid #2c3340; color: #f2a93b; font-size: 1.5rem; font-weight: 600;
    font-family: inherit; padding: 0.1rem 0.15rem 0.3rem; outline: none; }
  .ask-input::placeholder { color: #3c4452; font-weight: 500; }
  .ask-input:focus { border-bottom-color: #f2a93b; }
  .ask-input::selection { background: rgba(242,169,59,0.3); color: #ffd699; }
  .shutter { flex: none; width: 34px; height: 34px; border-radius: 50%;
    border: 2px solid #f2a93b; background: transparent; cursor: pointer;
    display: flex; align-items: center; justify-content: center; transition: background 0.15s; }
  .shutter:hover { background: rgba(242,169,59,0.15); }
  .shutter:disabled { opacity: 0.35; cursor: default; }
  .shutter svg { width: 12px; height: 12px; }

  .viewfinder { position: relative; width: 100%; max-width: 440px; aspect-ratio: 1 / 1;
    background: #0d1015; border-radius: 6px; overflow: hidden; }
  .vf-corner { position: absolute; width: 22px; height: 22px; border-color: #f2a93b; opacity: 0.85; z-index: 2; }
  .vf-corner.tl { top: 12px; left: 12px; border-top: 3px solid; border-left: 3px solid; }
  .vf-corner.tr { top: 12px; right: 12px; border-top: 3px solid; border-right: 3px solid; }
  .vf-corner.bl { bottom: 12px; left: 12px; border-bottom: 3px solid; border-left: 3px solid; }
  .vf-corner.br { bottom: 12px; right: 12px; border-bottom: 3px solid; border-right: 3px solid; }
  .vf-content { position: absolute; inset: 0; z-index: 1; display: flex; align-items: center; justify-content: center; }
  .vf-hint { color: #4c566a; font-size: 0.85rem; text-align: center; padding: 0 2.5rem; line-height: 1.5; }
  .vf-hint.err-text { color: #f87171; }
  .vf-content img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover;
    opacity: 0; filter: blur(16px); transition: opacity 0.6s ease, filter 0.6s ease; }
  .vf-content img.loaded { opacity: 1; filter: blur(0); }
  .vf-pulse { width: 10px; height: 10px; border-radius: 50%; background: #f2a93b;
    animation: pulse 1.1s ease-in-out infinite; }
  @keyframes pulse { 0%, 100% { opacity: 0.25; transform: scale(0.85); } 50% { opacity: 1; transform: scale(1); } }

  .vf-actions { width: 100%; max-width: 440px; display: flex; justify-content: center;
    gap: 1.5rem; margin-top: 1rem; font-size: 0.82rem; min-height: 1.2rem; }
  .vf-actions button, .vf-actions a { background: none; border: none; color: #8c95a5;
    cursor: pointer; font-size: 0.82rem; font-family: inherit; text-decoration: none; padding: 0; }
  .vf-actions button:hover, .vf-actions a:hover { color: #f2a93b; }

  .examples { width: 100%; max-width: 900px; margin-top: 3rem; }
  .examples h2 { font-size: 0.85rem; font-weight: 600; color: #4c566a; text-align: center;
    margin-bottom: 1rem; text-transform: uppercase; letter-spacing: 0.08em; }
  .ex-row { display: flex; gap: 1rem; overflow-x: auto; padding: 0.25rem 0.25rem 0.75rem;
    scroll-snap-type: x proximity; -webkit-overflow-scrolling: touch; }
  .ex-card { flex: 0 0 180px; scroll-snap-align: start; cursor: pointer;
    background: #12161e; border: 1px solid #1f2733; border-radius: 12px; overflow: hidden;
    transition: border-color 0.15s; }
  .ex-card:hover { border-color: #f2a93b; }
  .ex-card img { width: 100%; height: 140px; object-fit: cover; display: block; background: #0b0e13; }
  .ex-card .ex-title { padding: 0.5rem 0.6rem; font-size: 0.72rem; color: #c3cad6; line-height: 1.3;
    max-height: 2.6em; overflow: hidden;
    display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }

  .footer { margin-top: 2.5rem; color: #4c566a; font-size: 0.75rem; text-align: center; }
  .footer a { color: #8c95a5; text-decoration: none; }
</style>
</head>
<body>
  <div class="wordmark">InstantImages</div>

  <div class="ask">
    <span class="ask-prefix">Show me</span>
    <input type="text" id="prompt" class="ask-input" enterkeyhint="go"
           placeholder="a lighthouse in a storm at golden hour..." autofocus>
    <button class="shutter" id="shutter" onclick="generate()" title="Look" aria-label="Generate">
      <svg viewBox="0 0 24 24" fill="none" stroke="#f2a93b" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round">
        <path d="M5 12h14M13 6l6 6-6 6"/>
      </svg>
    </button>
  </div>

  <div class="viewfinder" id="viewfinder">
    <div class="vf-corner tl"></div><div class="vf-corner tr"></div>
    <div class="vf-corner bl"></div><div class="vf-corner br"></div>
    <div class="vf-content" id="vf-content">
      <div class="vf-hint" id="vf-hint">press enter to look</div>
      <img id="img" alt="">
    </div>
  </div>

  <div class="vf-actions" id="vf-actions">
    <button onclick="surpriseMe()">surprise me</button>
    <a href="#" id="dl" download="instant-image.jpg" style="display:none">download</a>
  </div>

  <div class="examples">
    <h2>Recently shown</h2>
    <div class="ex-row" id="ex-row"></div>
  </div>
  <div class="footer">
    <p>Powered by AI · <a href="https://byclaude.net">by Claude</a> · <a href="https://instantvideos.org">InstantVideos.org</a> · ~$0.03 per image</p>
  </div>
<script>
let inFlight = false;

function setHint(text, isErr) {
  const hint = document.getElementById('vf-hint');
  hint.textContent = text;
  hint.style.display = 'block';
  hint.classList.toggle('err-text', !!isErr);
  document.getElementById('img').classList.remove('loaded');
}

async function surpriseMe() {
  const input = document.getElementById('prompt');
  input.value = '...';
  setHint('looking around...');
  const resp = await fetch('/surprise');
  const data = await resp.json();
  input.value = data.prompt;
  generate();
}

async function generate() {
  let prompt = document.getElementById('prompt').value.trim();
  if (!prompt || prompt === '...' || inFlight) return;
  clearTimeout(typeaheadTimer);
  inFlight = true;
  const shutter = document.getElementById('shutter');
  const dl = document.getElementById('dl');
  shutter.disabled = true;
  dl.style.display = 'none';
  setHint('developing...');

  try {
    const resp = await fetch('/generate', {
      method: 'POST',
      headers: {'Content-Type': 'application/x-www-form-urlencoded'},
      body: 'prompt=' + encodeURIComponent(prompt)
    });
    const data = await resp.json();
    if (data.error) {
      setHint(data.error, true);
    } else {
      const img = document.getElementById('img');
      img.onload = () => { img.classList.add('loaded'); };
      img.src = 'data:image/png;base64,' + data.image;
      document.getElementById('vf-hint').style.display = 'none';
      dl.href = 'data:image/png;base64,' + data.image;
      dl.style.display = 'inline';
    }
  } catch(e) {
    setHint('Network error — please try again.', true);
  }
  shutter.disabled = false;
  inFlight = false;
}

const EXAMPLES = ${JSON.stringify(EXAMPLES)};
function renderExamples() {
  const row = document.getElementById('ex-row');
  row.innerHTML = EXAMPLES.map((ex, i) =>
    '<div class="ex-card" onclick="useExample(' + i + ')">' +
    '<img src="data:image/jpeg;base64,' + ex.data + '" loading="lazy" alt="">' +
    '<div class="ex-title">' + ex.prompt + '</div></div>'
  ).join('');
}
function useExample(i) {
  document.getElementById('prompt').value = EXAMPLES[i].prompt;
  generate();
}
renderExamples();

document.getElementById('prompt').addEventListener('keydown', e => {
  const input = e.target;
  if (e.key === 'Enter') { e.preventDefault(); generate(); return; }
  // Tab accepts a pending ghost suggestion instead of leaving the field —
  // →/End already do this for free (native behavior collapses a selection
  // to its end on arrow-right), Tab needs it done explicitly.
  if (e.key === 'Tab' && input.selectionStart !== input.selectionEnd) {
    e.preventDefault();
    input.setSelectionRange(input.value.length, input.value.length);
  }
});

// Type-ahead ghost text — browser-address-bar style: the suggested tail is
// inserted as SELECTED text, so continuing to type naturally overwrites it,
// and →/Tab/End accept it for free via native selection-collapse behavior.
let typeaheadTimer = null;
document.getElementById('prompt').addEventListener('input', () => {
  const input = document.getElementById('prompt');
  clearTimeout(typeaheadTimer);
  // only suggest when the caret is at the very end — mid-sentence ghosting
  // is a confusing UX and not worth the complexity here
  if (input.selectionStart !== input.value.length || input.selectionEnd !== input.value.length) return;
  const typed = input.value;
  if (typed.trim().length < 4) return;
  typeaheadTimer = setTimeout(async () => {
    try {
      const resp = await fetch('/typeahead', {
        method: 'POST',
        headers: {'Content-Type': 'application/x-www-form-urlencoded'},
        body: 'prefix=' + encodeURIComponent(typed)
      });
      const data = await resp.json();
      // discard if stale — the user kept typing, or a generation already started, while we waited
      if (inFlight || input.value !== typed) return;
      if (data.completion) {
        input.value = typed + data.completion;
        input.setSelectionRange(typed.length, input.value.length);
      }
    } catch (e) { /* silent — best-effort nicety, never worth surfacing an error for */ }
  }, 300);
});
</script>
</body>
</html>`;


function cleanPrompt(text) {
  if (!text) return '';
  let p = text.trim().replace(/^["*\`]+|["*\`]+$/g, '').trim();
  // strip leading numbering / reasoning prefixes
  while (p && p[0] && '0123456789.-*# '.includes(p[0])) p = p.slice(1).trimStart();
  return p;
}


export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    // ── Homepage ──────────────────────────────────────────────────────────
    if (url.pathname === '/' || url.pathname === '/index.html') {
      return new Response(HTML_PAGE, {
        headers: { 'Content-Type': 'text/html; charset=utf-8' },
      });
    }

    // ── SEO surface ───────────────────────────────────────────────────────
    // Added 2026-07-31. Neither of these existed before, so the origin 404'd
    // and Cloudflare answered robots.txt with its synthetic content-signals
    // stub — no crawl guidance, no Sitemap: directive. A citation audit that
    // day found instantimages.org wasn't registered in Bing Webmaster at all
    // and had zero impressions, while same-age competitor image-gen EMDs
    // (freeimggen.com, 30 days old) were being cited by AI search. The gap was
    // indexation, not positioning copy.
    if (url.pathname === '/robots.txt') {
      return new Response(
        'User-agent: *\nAllow: /\n\nSitemap: https://instantimages.org/sitemap.xml\n',
        { headers: { 'Content-Type': 'text/plain; charset=utf-8',
                     'Cache-Control': 'public, max-age=86400' } },
      );
    }
    if (url.pathname === '/sitemap.xml') {
      const today = new Date().toISOString().slice(0, 10);
      return new Response(
        '<?xml version="1.0" encoding="UTF-8"?>\n' +
        '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n' +
        '  <url>\n' +
        '    <loc>https://instantimages.org/</loc>\n' +
        `    <lastmod>${today}</lastmod>\n` +
        '    <changefreq>daily</changefreq>\n' +
        '    <priority>1.0</priority>\n' +
        '  </url>\n' +
        '</urlset>\n',
        { headers: { 'Content-Type': 'application/xml; charset=utf-8',
                     'Cache-Control': 'public, max-age=86400' } },
      );
    }

    // ── Surprise me ───────────────────────────────────────────────────────
    // Cerebras hosts gpt-oss-120b on inference hardware fast enough that this
    // round-trip disappears into the same "instant" feel as the image itself
    // (~50-300ms server-side vs. multiple seconds elsewhere). reasoning_effort
    // "low" matters — gpt-oss is a reasoning model that will otherwise burn
    // its whole max_tokens budget on hidden reasoning and never emit content.
    if (url.pathname === '/surprise') {
      try {
        const cbResp = await fetch(CEREBRAS_URL, {
          method: 'POST',
          headers: {
            'Authorization': `Bearer ${env.CEREBRAS_API_KEY}`,
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            model: 'gpt-oss-120b',
            max_tokens: 300,
            temperature: 1.2,
            reasoning_effort: 'low',
            messages: [{ role: 'user', content: SURPRISE_PROMPT }],
          }),
        });
        const cbData = await cbResp.json();
        const msg = cbData.choices?.[0]?.message;
        let prompt = cleanPrompt(msg?.content || '');
        if (!prompt || prompt.length < 10) {
          prompt = FALLBACK_PROMPTS[Math.floor(Math.random() * FALLBACK_PROMPTS.length)];
        }
        return Response.json({ prompt });
      } catch (e) {
        return Response.json({
          prompt: FALLBACK_PROMPTS[Math.floor(Math.random() * FALLBACK_PROMPTS.length)],
        });
      }
    }

    // ── Type-ahead completion ─────────────────────────────────────────────
    // Ghost-text continuation while the user is still typing, browser-address-
    // -bar style (client selects the suggested tail so typing overwrites it,
    // →/Tab accepts it). Fails silently to "" on any error or short prefix —
    // this is a best-effort nicety, never worth showing something broken for.
    if (url.pathname === '/typeahead' && request.method === 'POST') {
      try {
        const form = await request.formData();
        const prefix = (form.get('prefix') || '').toString();
        if (prefix.trim().length < 4) {
          return Response.json({ completion: '' });
        }
        const cbResp = await fetch(CEREBRAS_URL, {
          method: 'POST',
          headers: {
            'Authorization': `Bearer ${env.CEREBRAS_API_KEY}`,
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            model: 'gpt-oss-120b',
            max_tokens: 700,
            temperature: 0.8,
            reasoning_effort: 'low',
            messages: [{ role: 'user', content: typeaheadPrompt(prefix) }],
          }),
        });
        const cbData = await cbResp.json();
        const raw = cbData.choices?.[0]?.message?.content || '';
        const completion = parseTypeahead(prefix, raw);
        return Response.json({ completion });
      } catch (e) {
        return Response.json({ completion: '' });
      }
    }

    // ── Generate image ────────────────────────────────────────────────────
    if (url.pathname === '/generate' && request.method === 'POST') {
      try {
        const form = await request.formData();
        const prompt = (form.get('prompt') || '').trim();
        const ar = form.get('ar') || '1:1';

        if (!prompt) {
          return Response.json({ error: 'no prompt' }, { status: 400 });
        }

        const geminiResp = await fetch(`${GEMINI_URL}?key=${env.GEMINI_API_KEY}`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            contents: [{ parts: [{ text: prompt }] }],
            generationConfig: {
              responseModalities: ['IMAGE', 'TEXT'],
              imageConfig: { aspectRatio: ar },
            },
            service_tier: 'priority',
          }),
        });

        const geminiData = await geminiResp.json();
        const candidates = geminiData.candidates || [];
        if (candidates.length > 0) {
          const parts = candidates[0].content?.parts || [];
          for (const part of parts) {
            const inlineData = part.inlineData || part.inline_data;
            if (inlineData?.data) {
              return Response.json({ image: inlineData.data });
            }
          }
        }

        // Check for quota / rate limit errors
        const errStr = JSON.stringify(geminiData).toLowerCase();
        if (errStr.includes('429') || errStr.includes('quota') || errStr.includes('resource_exhausted')) {
          return Response.json({
            error: 'Our image credits just ran out — we are topping up now. Please try again in a few minutes.',
          });
        }
        return Response.json({ error: 'Image generation failed — please try a different prompt.' });
      } catch (e) {
        return Response.json({ error: 'Network error — please try again.' });
      }
    }

    return new Response('Not found', { status: 404 });
  },
};
